input.onfocus:
if (!this.ac)
									addLoadEvent(function() {
																var e = gel('sys_display.${jvar_html_identifier}');
																if (!e.ac)
																	new AJAXReferenceCompleter(e, '${jvar_html_identifier}', '${jvar_dependent}', '${jvar_ref_qual_elements}', '${jvar_reference}');
												})

j:jelly.script:
var mappedField = null;

// Alter the label attribute to ensure it still works whilst still allowing the GlideListElement logic to work
var selectLabelElem = $$("label[for='${jvar_label_for_value}']");
if (selectLabelElem ${AND} selectLabelElem.length === 1)
	selectLabelElem[0].writeAttribute('for', 'select_0${jvar_html_identifier}');

addUnloadEvent(function() {
	var element = gel("sys_display.${jvar_html_identifier}");
	if (element ${AND} element.ac) {
		if (element.ac.destroy){
			element.ac.destroy();
		}
	}
});

function addChoiceLocal(fieldid) {
	var selectBox = gel('select_0'+fieldid);
	var value = gel(fieldid).value;
	var displayWidget = gel('sys_display.' + fieldid);
	var display = displayWidget.value;
	displayWidget.value= '';
	var select = new Select('select_0'+fieldid);
	// don't add duplicates
	if (select.contains(value)) {
		return;
	}
	var opt = document.createElement("option");
	opt.value = value;
	opt.text = display;

	selectBox.options.add(opt);
	synchLists(fieldid);
}

function addChoiceExternal(fieldid, value, displayValue) {
	var selectBox = gel('select_0'+fieldid);
	var opt = document.createElement("option");
	opt.value = value;
	opt.text = displayValue;
	selectBox.options.add(opt);
	synchLists(fieldid);
}

function synchLists(fieldid) {
	var sel0 = gel('select_0' + fieldid);
	var distribution = gel(fieldid);
	var ovalue = distribution.value;
	saveAllSelected([ sel0 ], [ distribution ], ',', '\\', '--None--');
}

function openGlidePopupSelection(event, table) {
	var select = gel('select_0${jvar_html_identifier}');
	var sysid = glideListGetSelected(select);
	if (sysid) {
		// If we get here, there is only one item selected. When multiple items are selected
		// toggleGlideListIcons disables the Info icon
		gel("${jvar_html_identifier}SELECTED").value = sysid;
		gel("${jvar_html_identifier}SELECTEDTABLE").value = table;
		popLightWeightReferenceDiv(event, '${jvar_html_identifier}SELECTED', true);
	}
}
